/* a trigger that names the model and how hard it thinks, over the open list: speed, quality and cost as five-step meters
   with the real numbers on hover, and the thinking effort under them as a small dropdown */
.dm-mpk{position:relative;display:flex;flex-direction:column;gap:var(--dm-s-2);width:100%;max-width:420px;margin:0 auto}
.dm-mpk-top{display:flex;align-items:center;justify-content:space-between;gap:10px;padding:0 2px}
.dm-mpk-lb{font-size:12.5px}
.dm-mpk-tr{display:inline-flex;align-items:center;gap:7px;height:32px;padding:0 10px 0 6px;border-radius:var(--dm-r-pill);background:var(--dm-surface);box-shadow:var(--dm-shadow);font-size:13px;font-weight:500;white-space:nowrap;transition:box-shadow .16s}
@media (hover:hover) and (pointer:fine){.dm-mpk-tr:hover{box-shadow:var(--dm-shadow-pop)}}
.dm-mpk-tr>svg{color:var(--dm-muted);transition:transform .32s var(--dm-ease)}
.dm-mpk-tr[aria-expanded="true"]>svg{transform:rotate(180deg)}
.dm-mpk-tr:focus-visible{outline:2px solid var(--dm-focus);outline-offset:2px}
.dm-mpk-ef{font-weight:400;font-size:12.5px}
/* each model's mark carries the letter colour that reads on it (--mt): on the accent fill that is --on-accent */
.dm-mpk-mk{width:20px;height:20px;border-radius:6px;display:grid;place-items:center;font-size:11px;font-weight:500;color:var(--dm-mt,var(--dm-on-ink));background:var(--dm-mc,var(--dm-fg2));flex:none;transition:background .32s}
.dm-mpk-p{padding:6px;display:flex;flex-direction:column}
.dm-mpk-hd,.dm-mpk-o{display:grid;grid-template-columns:20px minmax(0,1fr) repeat(3,34px);align-items:center;gap:10px}
.dm-mpk-hd{padding:var(--dm-s-1) 10px 2px;font-size:11px;color:var(--dm-muted)}
.dm-mpk-hd span{text-align:center}
.dm-mpk-o{width:100%;padding:var(--dm-s-2) 10px;border-radius:var(--dm-r-in);text-align:left;font-size:13px;transition:background .16s}
@media (hover:hover) and (pointer:fine){.dm-mpk-o:hover{background:var(--dm-row)}}
.dm-mpk-o[aria-checked="true"]{background:var(--dm-sel)}
.dm-mpk-o[aria-checked="true"] .dm-d{color:var(--dm-fg2)}
.dm-mpk-o:focus-visible{outline:2px solid var(--dm-focus);outline-offset:-2px}
.dm-mpk-o .dm-t{display:flex;flex-direction:column;min-width:0}
.dm-mpk-o .dm-t b{font-weight:500;display:flex;align-items:center;gap:6px}
.dm-mpk-o .dm-ck{display:grid;color:var(--dm-accent-fg,var(--dm-accent));opacity:0;transform:scale(.6);transition:opacity .16s,transform .32s var(--dm-ease)}
.dm-mpk-o[aria-checked="true"] .dm-ck,.dm-mpk-o .dm-ck:has(.dm-spin){opacity:1;transform:none}
.dm-mpk-o .dm-ck .dm-spin{width:10px;height:10px;color:var(--dm-muted)}
.dm-mpk-o .dm-d{font-size:12px;color:var(--dm-muted);white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.dm-mpk-o.dm-busy .dm-d{color:var(--dm-warn)}
.dm-mpk-o.dm-busy .dm-mpk-mk{background:var(--dm-warn);color:var(--dm-on-ink)}
.dm-mpk-m{display:flex;gap:2px;height:8px}
.dm-mpk-m i{flex:1;border-radius:2px;background:var(--dm-rail);transition:background .32s}
.dm-mpk-m i.dm-on{background:var(--dm-fg2)}
.dm-mpk-o[aria-checked="true"]:not(.dm-busy) .dm-mpk-m i.dm-on{background:var(--dm-accent-mark,var(--dm-accent))}
/* the way out when a model can't take the request: wait for it, or a close match that starts now */
.dm-mpk-sg{margin:var(--dm-s-1) var(--dm-s-1) 2px;padding:10px var(--dm-s-3);border-radius:var(--dm-r-in);background:var(--dm-warn-bg);display:flex;flex-direction:column;gap:var(--dm-s-2)}
.dm-mpk-sgt{margin:0;font-size:12.5px;line-height:1.45}
.dm-mpk-sga{display:flex;justify-content:flex-end;flex-wrap:wrap;gap:6px}
/* on the amber notice the secondary button is white, not grey */
.dm-mpk-sg .dm-pill.dm-ghost{background:var(--dm-surface);color:var(--dm-fg);box-shadow:var(--dm-shadow)}
@media (hover:hover) and (pointer:fine){.dm-mpk-sg .dm-pill.dm-ghost:hover{box-shadow:var(--dm-shadow-pop)}}
.dm-mpk-th{display:flex;align-items:center;justify-content:space-between;flex-wrap:wrap;gap:var(--dm-s-2) var(--dm-s-3);padding:var(--dm-s-3) 10px 6px;margin:6px var(--dm-s-1) 0;border-top:1px solid color-mix(in srgb,var(--dm-line) 50%,transparent)}
.dm-mpk-thh{display:flex;flex-direction:column;min-width:0;font-size:13px}
.dm-mpk-thh b{font-weight:500;display:flex;align-items:center;gap:6px}
.dm-mpk-thh b svg{color:var(--dm-muted)}
.dm-mpk-thd{font-size:12px}
.dm-mpk-eb{display:inline-flex;align-items:center;gap:6px;height:28px;padding:0 var(--dm-s-2) 0 10px;border-radius:var(--dm-r-pill);background:var(--dm-chip);font-size:13px;transition:background .16s}
.dm-mpk-eb[aria-expanded="true"]{background:var(--dm-hover)}
@media (hover:hover) and (pointer:fine){.dm-mpk-eb:hover{background:var(--dm-hover)}}
.dm-mpk-eb>svg{color:var(--dm-muted);transition:transform .32s var(--dm-ease)}
.dm-mpk-eb[aria-expanded="true"]>svg{transform:rotate(180deg)}
.dm-mpk-pop{min-width:220px}
.dm-mpk-note{margin:0;padding:0 2px;font-size:12.5px;min-height:20px;display:flex;align-items:center;gap:6px}
.dm-mpk-note svg{color:var(--dm-ok);flex:none}
/* phones: the line under each name wraps, and the meters keep room for their labels */
/* on a phone the meters close up so a model's line keeps two or three words to a row */
@media (max-width:480px){.dm-mpk-hd,.dm-mpk-o{grid-template-columns:20px minmax(0,1fr) repeat(3,34px);gap:6px}.dm-mpk-hd{font-size:10.5px;padding-inline:6px}.dm-mpk-o{padding-inline:6px}.dm-mpk-o .dm-d{white-space:normal}}

